// Illustrative Java for the reduced IR model. NOT a compiled or executed JIR input.
// The real project uses a String taskId and several containers. This reduction
// treats taskId as an untyped payload cursor. It does not establish JVM type/path
// feasibility or claim that Header/StrTokenizer models coexist at a project call.
Object root(Object taskId) {
    // Source rule: assign T to taskId at entry, including its payload fields.
    Object r = payload(taskId);
    sinkOnMapValue(r); // Sink rule: ContainsMark(r.[java.util.Map#MapValue], T).
    return r;
}
Object payload(Object taskId) {
    Object x = taskId;
    while (choose()) {
        // Unknown iterator payload call: selected real serialized next models
        // H=HeaderElementIterator.storage, I=Iterator.Element, S=StrTokenizer.storage.
        x = modeledNext(x);
        if (recursiveArm()) x = payload(x);
    }
    return x;
}
// The production test uses three separate CFG reductions:
// LOOP_ONLY: keep the while, remove the recursive call.
// RECURSION_ONLY: choose zero/one body step, no CFG back-edge, keep the recursive call.
// COMBINED: keep both the CFG loop and recursive call.
// No method transfer is predefined. Every modeled next action has depth 0 or 1.

conductor-growth-control.init.gradle.content:
def externalControlDir = System.getProperty('opentaint.conductorGrowthMetadataDir')
if (externalControlDir == null) throw new GradleException('Set -Dopentaint.conductorGrowthMetadataDir to the extracted control directory')
gradle.beforeProject { project ->
    if (project.name == 'opentaint-dataflow' && project.projectDir.parentFile.name == 'opentaint-dataflow-core') {
        project.plugins.withId('org.jetbrains.kotlin.jvm') {
            project.extensions.getByName('kotlin').sourceSets.getByName('test').kotlin.srcDir(externalControlDir)
        }
        project.tasks.withType(org.gradle.api.tasks.testing.Test).configureEach { test ->
            test.systemProperty('opentaint.conductorGrowthMetadataDir', externalControlDir)
            test.testLogging.showStandardStreams = true
        }
    }
}

