    "content": "package org.opentaint.dataflow.bidi

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.FieldAccessor
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.Seed
import org.opentaint.dataflow.bidi.fixtures.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.bidi.interp.CallPoint.*
import org.opentaint.dataflow.bidi.interp.StageKind.*
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import java.security.MessageDigest
import kotlin.test.*

/** PREPARED, NOT RUN: reduced untyped IR control. It is not a replay of the project IR. */
class ConductorVirtualIteratorGrowthControlTest {
    private enum class Shape(val loop: Boolean, val recursion: Boolean) {
        LOOP_ONLY(true, false), RECURSION_ONLY(false, true), COMBINED(true, true)
    }
    private val taskId = AccessPathBase.Argument(1)
    private val ret = AccessPathBase.Return
    private val x = AccessPathBase.LocalVar(0)
    private val thisBase = AccessPathBase.This
    private data class Metadata(val id: String, val source: String, val first: Int, val last: Int,
                                val from: String, val to: String, val field: FieldAccessor?)
    private val repository: Path get() = generateSequence(Paths.get("").toAbsolutePath()) { it.parent }
        .first { Files.isDirectory(it.resolve("model/java/config")) }
    private fun metadata(): List<Metadata> {
        val directory = Paths.get(checkNotNull(System.getProperty("opentaint.conductorGrowthMetadataDir")) {
            "Set opentaint.conductorGrowthMetadataDir to the external prepared control directory"
        })
        return Files.readAllLines(directory.resolve("metadata.tsv")).filterNot { it.startsWith("#") || it.isBlank() }
            .map { line ->
                val p = line.split('\t')
                check(p.size == 8)
                val bytes = Files.readAllBytes(repository.resolve(p[1]))
                val sha = MessageDigest.getInstance("SHA-256").digest(bytes)
                    .joinToString("") { "%02x".format(it.toInt() and 255) }
                assertEquals(p[2], sha, "The real serialized model changed; re-extract and review it")
                val field = if (p[7] == "-") null else p[7].removePrefix(".").split('#').let {
                    check(it.size == 3); FieldAccessor(it[0], it[1], it[2])
                }
                Metadata(p[0], p[1], p[3].toInt(), p[4].toInt(), p[5], p[6], field)
            }
    }
    private fun summary(vararg edges: PathEdge) = StatementSummary(edges.map { it.from.base }.toSet(),
        edges.map(MicroEdge::of), emptyList(), emptyMap())

    /** Actual one-field serialized actions; no method summary or deep relation is supplied. */
    private fun nextPlan(f: FiniteProgramFixtures, rows: List<Metadata>): CallPlan {
        val edges = rows.filter { it.id in setOf("H", "I", "S") }.map { row ->
            assertEquals("this", row.from); assertEquals("result", row.to)
            val path = row.field?.let { listOf(f.ap.accessors.index(it)) }.orEmpty()
            assertTrue(path.size <= 1)
            starEdge(thisBase, path, ret, emptyList())
        }
        return CallPlan(setOf(x), listOf(
            CallStage.Edges(BEFORE, BOUND, BIND_IN, summary(starEdge(x, emptyList(), thisBase, emptyList()), ZERO_KEEP)),
            CallStage.Actions(BOUND, ADDED, emptyList()),
            CallStage.Edges(ADDED, RETURNED, UNRESOLVED, StatementSummary.identities(setOf(thisBase, AccessPathBase.Zero))),
            CallStage.Edges(ADDED, RETURNED, UNRESOLVED, summary(*edges.toTypedArray())),
            CallStage.Actions(RETURNED, REWRITTEN, emptyList()),
            CallStage.Edges(REWRITTEN, AFTER, BIND_BACK,
                summary(starEdge(ret, emptyList(), x, emptyList()),
                    starEdge(thisBase, emptyList(), x, emptyList()), ZERO_KEEP)),
        ), emptyList(), BEFORE, AFTER)
    }
    private fun call(callee: MethodKey, from: AccessPathBase, into: AccessPathBase,
                     returnTo: AccessPathBase): CallPlan = CallPlan(setOf(from, returnTo), listOf(
        CallStage.Edges(BEFORE, BOUND, BIND_IN, summary(starEdge(from, emptyList(), into, emptyList()), ZERO_KEEP)),
        CallStage.Actions(BOUND, ADDED, emptyList()),
        CallStage.Callees(ADDED, RETURNED, listOf(callee)),
        CallStage.Actions(RETURNED, REWRITTEN, emptyList()),
        CallStage.Edges(REWRITTEN, AFTER, BIND_BACK, summary(starEdge(ret, emptyList(), returnTo, emptyList()), ZERO_KEEP)),
    ), emptyList(), BEFORE, AFTER)

    @Test fun `real virtual iterator actions create the captured mixed family in a loop`() = run(Shape.LOOP_ONLY)
    @Test fun `real virtual iterator actions also run with a recursive helper and a loop`() = run(Shape.COMBINED)
    @Test fun `an acyclic body isolates recursive summary feedback under the same paired budget`() = run(Shape.RECURSION_ONLY)

    private fun run(shape: Shape) = FiniteProgramFixtures().use { f ->
        val models = metadata()
        fun field(id: String) = f.ap.accessors.index(models.single { it.id == id && it.field != null }.field!!)
        val h = field("H"); val s = field("S"); val v = field("V")
        val t = MarkSlot.Concrete(f.mark("T"))
        val rootMethod = f.method("reduced-ParametersUtils-root-$shape", listOf(listOf(1), listOf(2), emptyList()), 2)
        val root = rootMethod.key()
        // Forward: 0 entry; 1 x=taskId; 2 choose; 3 x=next(x); 4 recursive helper; 5 return x; 6 exit.
        val adjacency = listOf(listOf(1), listOf(2), listOf(3, 5),
            listOf(if (shape.recursion) 4 else if (shape.loop) 2 else 5),
            listOf(if (shape.loop) 2 else 5), listOf(6), emptyList())
        val walkMethod = f.method("reduced-ParametersUtils-payload-$shape", adjacency, 6)
        val walk = walkMethod.key()
        val producer = PathEdge(ZERO_FACT, PathFact(taskId, emptyList(), Tail.ANY_TAINT, t), ExclusionSet.Empty)
        f.entry(root, RuleStatement(summary(ZERO_KEEP, producer), StatementSummary.EMPTY, emptyList()))
        f.call(root, 1, call(walk, taskId, taskId, ret))
        val check = f.pattern(ret, listOf(v), Tail.EXACT, t)
        val sink = localSink(listOf(check), id = "reduced-ParametersUtils-sink")
        f.exit(root, 2, ExitRules(RuleStatement(StatementSummary.EMPTY, StatementSummary.EMPTY, listOf(sink)), false, emptySet()))
        f.statement(walk, 1, MicroEdgeBuilder().apply { move(x, taskId) }.build())
        f.call(walk, 3, nextPlan(f, models))
        if (shape.recursion) f.call(walk, 4, call(walk, x, taskId, x))
        f.statement(walk, 5, MicroEdgeBuilder().apply { move(ret, x) }.build())

        // These are query inputs, not fabricated transfer summaries. The sink seed is shallow: only V.
        val pair = DemandPattern(f.pattern(ret, tail = Tail.ANY, mark = MarkSlot.STAR),
            f.pattern(taskId, tail = Tail.STAR, mark = MarkSlot.STAR))
        val zero = f.ap.zero.toPattern()
        val config = f.config(index = 4, L = 3, roots = listOf(root),
            demand = listOf(root to DemandPattern(zero, zero), walk to pair),
            seeds = listOf(Seed.Sink(sink.rule, root, rootMethod.inst(2), check)))
        assertTrue(config.records.byEntry(walk, pair.entry).none(), "No saved transfer is injected")
        assertTrue(f.callInputs.flatMap { it.plan.stages }.none { it is CallStage.Predefined })
        val schedule = ProductionSchedule(f, config, policy = SchedulePolicy.FIFO, quantum = 1)
        val result = schedule.run()
        val inWalk = result.processed.filter { it.method == walk }
        val maxDepth = inWalk.maxOfOrNull { it.conclusion.fact.path.count { a -> a.isCounted() } } ?: 0
        val admitted = result.rawSummaries.filter { it.method == walk }
        assertTrue(admitted.isNotEmpty(), "The helper summaries must be inferred")
        assertTrue(admitted.all { it.conclusion.fact.path.count { a -> a.isCounted() } <= 1 })
        println("CONDUCTOR_REDUCED shape=$shape processed=${inWalk.size} maxBodyFL=$maxDepth admitted=${admitted.size} subscriptions=${schedule.subscriptions.size}")

        if (!shape.loop) {
            // This is the recursion-only negative control. Do not assert an unmeasured H.H.H result.
            println("CONDUCTOR_RECURSION_ONLY bodyPaths=${inWalk.map { it.conclusion.fact.path }.toSet()}")
            return@use
        }
        val target = listOf(s, h, v) // Captured case C: StrTokenizer.storage / HeaderElementIterator.storage / MapValue.
        val rawCandidate = inWalk.firstOrNull { it.node == walkMethod.inst(0) && it.conclusion.fact.base == taskId &&
            it.conclusion.fact.path == target && it.conclusion.fact.mark is MarkSlot.Star &&
            it.conclusion.fact.tail == Tail.STAR && !it.conclusion.demand }
        assertNotNull(rawCandidate,
            "Do not weaken this: the reduced engine must actually generate the captured mixed depth-3 family")
        val original = f.ap.premiseOf(rawCandidate.premise.map { f.ap.initial(it) })
        val raw = f.ap.factsOf(rawCandidate.conclusion.fact, rawCandidate.conclusion.exclusion, Layer.NORMAL)
        val normalized = normalizeFlowSummary(f.ap, original, raw)
        val gated = config.demand!!.intersect(walk, normalized.premise, normalized.facts, config.admissionPolicy)
        val expected = f.pattern(taskId, listOf(s), Tail.ANY, MarkSlot.STAR)
        assertContains(gated.flatMap { f.ops.leaves(it).toList() }, expected)
        assertTrue(gated.all { it.layer == Layer.DEMAND })
        assertTrue(admitted.any { it.premise == observedPremise(normalized.premise) &&
            it.conclusion == Conclusion(expected.fact, expected.exclusion, true) })
        println("CONDUCTOR_C5 shape=$shape A=${observedPremise(normalized.premise)} B=${rawCandidate.conclusion} Dc=${pair.entry} Dp=${pair.exit} budget=1 result=$expected/DEMAND")

        // In LOOP_ONLY this is the unique one-field creator of S.H.V: the S metadata action at call point 3.
        // The point observations are actual engine inputs; the model inverse maps H.V -> S.H.V.
        val before = inWalk.firstOrNull { it.node == walkMethod.inst(3) && it.conclusion.fact.base == x &&
            it.conclusion.fact.path == listOf(h, v) && it.premise == rawCandidate.premise }
        val after = inWalk.firstOrNull { it.node == walkMethod.inst(2) && it.conclusion.fact.base == x &&
            it.conclusion.fact.path == target && it.premise == rawCandidate.premise }
        assertNotNull(before, "The actual call input H.V must be observed")
        assertNotNull(after, "The actual delivery after the call must contain S.H.V")
        val creator = models.single { it.id == "S" && it.field != null }
        println("CONDUCTOR_CREATION shape=$shape input=$before model=${creator.source}:${creator.first}-${creator.last} action=this.S.*->result.* inverse=result.P.*->this.S.P.* output=$after")
    }
}
